#!/usr/bin/env node
// Regenerates the parts of this repository that mirror the live Minds MCP
// surface, so the documentation never drifts from the server:
//
//   - README.md, between <!-- tools:start --> and <!-- tools:end -->
//   - reference/tools.md (whole file)
//   - integrations/microsoft-mcp/mcptools.json
//   - "version" in every plugin/extension manifest
//
// Sources (all public, all generated by the server's code):
//   - https://getminds.ai/.well-known/mcp/server-card.json  (required)
//   - https://getminds.ai/api/public/mcp                   (optional, used when it answers 200)
//   - the ai.getminds/minds registry manifest for the version (see resolveVersion)
//
// Usage:
//   node scripts/sync-mcp-surface.mjs          write changes
//   node scripts/sync-mcp-surface.mjs --check  exit 1 if anything would change or
//                                              a hand-written doc names a tool the
//                                              server does not expose
//
// No dependencies; Node 20+.

import { readFile, writeFile } from "node:fs/promises";
import path from "node:path";
import { fileURLToPath } from "node:url";

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const CARD_URL = process.env.MINDS_SERVER_CARD_URL || "https://getminds.ai/.well-known/mcp/server-card.json";
const PUBLIC_URL = process.env.MINDS_PUBLIC_MCP_URL || "https://getminds.ai/api/public/mcp";
const SERVER_JSON_URL = "https://raw.githubusercontent.com/minds-ai-co/webapp/main/server.json";
const REGISTRY_URL = "https://registry.modelcontextprotocol.io/v0/servers?search=ai.getminds/minds";
const REGISTRY_NAME = "ai.getminds/minds";

const CHECK = process.argv.includes("--check");

const MANIFESTS = [
  "plugin.json",
  ".codex-plugin/plugin.json",
  ".cursor-plugin/plugin.json",
  "gemini-extension.json",
  "integrations/microsoft-mcp/manifest.template.json",
];

// Hand-written pages that mention tools by name. They are not regenerated, but
// --check fails if they name a tool the live server does not expose.
const HAND_WRITTEN = [
  "README.md",
  "reference/index.md",
  "reference/connect.md",
  "reference/workflow.md",
  "reference/cookbook.md",
  "reference/scope.md",
  "integrations/microsoft-mcp/intro.md",
  "integrations/microsoft-mcp/README.md",
  "docs/index.html",
  "GEMINI.md",
];
const TOOL_TOKEN = /\b((?:list|get|ask|create|export|run|plan|manage|save|delete|import|duplicate|recalibrate|preview|chat|study|summarize|query|confirm)_[a-z_]+)\b/g;

async function fetchJson(url, { optional = false } = {}) {
  try {
    const response = await fetch(url, { headers: { Accept: "application/json" } });
    if (!response.ok) {
      if (optional) return null;
      throw new Error(`${url} answered ${response.status}`);
    }
    return await response.json();
  } catch (error) {
    if (optional) return null;
    throw error;
  }
}

function compareVersions(a, b) {
  const pa = String(a).split(".").map(Number);
  const pb = String(b).split(".").map(Number);
  for (let i = 0; i < 3; i += 1) {
    if ((pa[i] || 0) !== (pb[i] || 0)) return (pa[i] || 0) - (pb[i] || 0);
  }
  return 0;
}

// The registry manifest (webapp server.json) is the version authority. The
// webapp repository is private, so fall back to the public registry's latest
// entry for that manifest, then to the server card. Never move backwards: a
// manifest bumped ahead of the registry stays until the registry catches up.
async function resolveVersion(card, currentVersions) {
  const serverJson = await fetchJson(SERVER_JSON_URL, { optional: true });
  let version = serverJson?.version;
  let source = "webapp server.json";
  if (!version) {
    const registry = await fetchJson(REGISTRY_URL, { optional: true });
    const latest = registry?.servers?.find(
      (entry) =>
        entry.server?.name === REGISTRY_NAME &&
        entry._meta?.["io.modelcontextprotocol.registry/official"]?.isLatest,
    );
    version = latest?.server?.version;
    source = "official MCP registry (latest)";
  }
  if (!version) {
    version = card.serverInfo?.version;
    source = "server card serverInfo.version";
  }
  const highestCurrent = currentVersions.reduce(
    (max, value) => (compareVersions(value, max) > 0 ? value : max),
    "0.0.0",
  );
  if (compareVersions(highestCurrent, version) > 0) {
    return { version: highestCurrent, source: `${source} ${version}; kept higher manifest version` };
  }
  return { version, source };
}

const CATEGORIES = [
  ["Audiences", (name) => /audience/.test(name)],
  ["Guided research, drafts and templates", (name) =>
    /^(plan_study_questions|run_study_questions|list_research_methods|list_study_drafts|save_study_draft|list_study_templates|manage_study_template|delete_study_template)$/.test(name)],
  ["Minds", (name) => /(^|_)minds?(_|$)/.test(name)],
  ["Studies", () => true],
];

function categorize(tools) {
  const groups = new Map(CATEGORIES.map(([label]) => [label, []]));
  for (const tool of tools) {
    const [label] = CATEGORIES.find(([, test]) => test(tool.name));
    groups.get(label).push(tool);
  }
  // Sorted by name so the output does not depend on the card's ordering.
  return [...groups]
    .filter(([, list]) => list.length)
    .map(([label, list]) => [label, [...list].sort((a, b) => a.name.localeCompare(b.name))]);
}

function cell(text) {
  return String(text || "").replace(/\s+/g, " ").replace(/\|/g, "\\|").trim();
}

function firstSentence(description) {
  const flat = cell(description);
  const match = flat.match(/^(.+?[.!?])(\s|$)/);
  return match ? match[1] : flat;
}

function access(tool) {
  const a = tool.annotations || {};
  if (a.readOnlyHint) return "read-only";
  if (a.destructiveHint) return "destructive";
  return "writes";
}

function readmeBlock(tools, card) {
  const lines = [
    "<!-- Generated by scripts/sync-mcp-surface.mjs from the live server card. Do not edit by hand. -->",
    "",
    `The server advertises ${tools.length} tools. Clients read the current schemas at runtime;`,
    "the full list with access levels is in [reference/tools.md](reference/tools.md).",
    "",
    "| Area | Tool | What it does |",
    "| --- | --- | --- |",
  ];
  for (const [label, list] of categorize(tools)) {
    for (const tool of list) lines.push(`| ${label} | \`${tool.name}\` | ${firstSentence(tool.description)} |`);
  }
  lines.push("", `Server card: \`${CARD_URL}\` (\`${cell(card.serverInfo?.name)}\`).`);
  return lines.join("\n");
}

function toolsReference(tools, card, meta) {
  const out = [
    "<!-- Generated by scripts/sync-mcp-surface.mjs from the live server card. Do not edit by hand. -->",
    "",
    "# Tool reference",
    "",
    "The remote server is the source of truth for current schemas. This page is",
    "regenerated from the live server card; let the connected client inspect the",
    "live tool definition before constructing a call.",
    "",
    `The server advertises **${tools.length} tools** through ordinary \`tools/list\` discovery.`,
    "Access shows the tool annotations: `read-only` tools never change data,",
    "`destructive` tools can remove data and ask for confirmation.",
    "",
  ];
  for (const [label, list] of categorize(tools)) {
    out.push(`## ${label}`, "", "| Tool | Title | Purpose | Access |", "| --- | --- | --- | --- |");
    for (const tool of list) {
      out.push(`| \`${tool.name}\` | ${cell(tool.title || tool.annotations?.title)} | ${firstSentence(tool.description)} | ${access(tool)} |`);
    }
    out.push("");
  }

  const aliases = meta?.aliases || meta?.toolAliases;
  if (aliases && typeof aliases === "object" && Object.keys(aliases).length) {
    out.push(
      "## Legacy names",
      "",
      "Earlier tool names stay callable as aliases of the tools above. New",
      "integrations should call the advertised name.",
      "",
      "| Legacy name | Calls |",
      "| --- | --- |",
    );
    for (const [alias, target] of Object.entries(aliases).sort(([a], [b]) => a.localeCompare(b))) {
      out.push(`| \`${alias}\` | \`${typeof target === "string" ? target : target?.name ?? ""}\` |`);
    }
    out.push("");
  }

  const hidden = meta?.hiddenTools;
  if (Array.isArray(hidden) && hidden.length) {
    out.push(
      "## Registered but not advertised",
      "",
      "These tools are callable by exact name but are not part of the curated",
      "discovery response. Registry listings must not describe them as discovered.",
      "",
      "| Tool | Purpose |",
      "| --- | --- |",
    );
    for (const entry of hidden) {
      const name = typeof entry === "string" ? entry : entry?.name;
      const description = typeof entry === "string" ? "" : firstSentence(entry?.description);
      if (name) out.push(`| \`${name}\` | ${description} |`);
    }
    out.push("");
  }

  out.push(
    "## Discovery metadata",
    "",
    "| Resource | URL |",
    "| --- | --- |",
    `| MCP endpoint | \`${card.transport?.endpoint || "https://getminds.ai/mcp"}\` |`,
    `| Server card | \`${CARD_URL}\` |`,
    `| OAuth protected-resource metadata | \`${card.authorization?.protectedResourceMetadata || "https://getminds.ai/.well-known/oauth-protected-resource/mcp"}\` |`,
    `| Registry name | \`${REGISTRY_NAME}\` |`,
    "",
    "Authentication: OAuth 2.1 (dynamic client registration or Client ID Metadata",
    "Documents), or `Authorization: Bearer minds_...` with an API key from",
    "**Settings → API Keys**. MCP cannot create, rotate, or revoke the credential",
    "authenticating its own session.",
    "",
    "[Review the live API documentation](https://getminds.ai/api?utm_source=content&utm_medium=content&utm_campaign=content-seo-mcp-reference&utm_content=mcp-docs-tools)",
    "",
  );
  return out.join("\n");
}

function asciiJson(value) {
  return `${JSON.stringify(value, null, 2).replace(
    /[^\x00-\x7F]/g,
    (character) => `\\u${character.charCodeAt(0).toString(16).padStart(4, "0")}`,
  )}\n`;
}

const changed = [];
async function update(relativePath, next) {
  const file = path.join(ROOT, relativePath);
  const current = await readFile(file, "utf8").catch(() => "");
  if (current === next) return;
  changed.push(relativePath);
  if (!CHECK) await writeFile(file, next, "utf8");
}

const card = await fetchJson(CARD_URL);
const tools = Array.isArray(card.tools) ? card.tools : [];
if (!tools.length) throw new Error(`${CARD_URL} lists no tools`);
const names = new Set(tools.map((tool) => tool.name));
if (names.size !== tools.length) throw new Error("server card lists duplicate tool names");
const meta = await fetchJson(PUBLIC_URL, { optional: true });

// README tools block
const readmePath = path.join(ROOT, "README.md");
const readme = await readFile(readmePath, "utf8");
const START = "<!-- tools:start -->";
const END = "<!-- tools:end -->";
const startIndex = readme.indexOf(START);
const endIndex = readme.indexOf(END);
if (startIndex < 0 || endIndex < startIndex) throw new Error(`README.md needs ${START} and ${END} markers`);
await update(
  "README.md",
  `${readme.slice(0, startIndex + START.length)}\n${readmeBlock(tools, card)}\n${readme.slice(endIndex)}`,
);

// reference/tools.md
await update("reference/tools.md", toolsReference(tools, card, meta));

// Microsoft agent connector tool snapshot (ASCII-safe, as the package requires)
await update(
  "integrations/microsoft-mcp/mcptools.json",
  asciiJson({ tools: [...tools].sort((a, b) => a.name.localeCompare(b.name)) }),
);

// Manifest versions
const manifests = await Promise.all(
  MANIFESTS.map(async (relativePath) => {
    const raw = await readFile(path.join(ROOT, relativePath), "utf8");
    return { relativePath, raw, json: JSON.parse(raw) };
  }),
);
const { version, source } = await resolveVersion(card, manifests.map(({ json }) => json.version).filter(Boolean));
for (const { relativePath, raw, json } of manifests) {
  if (json.version === version) continue;
  const next = raw.replace(/("version"\s*:\s*")[^"]*(")/, `$1${version}$2`);
  await update(relativePath, next);
}

// Hand-written pages must not name tools the server does not expose.
const aliasNames = new Set(Object.keys(meta?.aliases || meta?.toolAliases || {}));
const stale = [];
for (const relativePath of HAND_WRITTEN) {
  let text = await readFile(path.join(ROOT, relativePath), "utf8").catch(() => "");
  if (relativePath === "README.md") {
    text = text.slice(0, text.indexOf(START)) + text.slice(text.indexOf(END));
  }
  for (const [, token] of text.matchAll(TOOL_TOKEN)) {
    if (!names.has(token)) stale.push(`${relativePath}: ${token}${aliasNames.has(token) ? " (legacy alias)" : ""}`);
  }
}

console.log(`Server card: ${tools.length} tools (${card.serverInfo?.name} ${card.serverInfo?.version})`);
console.log(`Public MCP metadata: ${meta ? "used" : "not available"}`);
console.log(`Manifest version: ${version} (${source})`);
console.log(changed.length ? `${CHECK ? "Out of date" : "Updated"}: ${changed.join(", ")}` : "Generated files are current.");
if (stale.length) console.log(`Hand-written pages name tools the server does not advertise:\n  ${[...new Set(stale)].join("\n  ")}`);
if (CHECK && (changed.length || stale.length)) process.exit(1);
